function cur_stats(array $rows, int $banksTotal, float $bestBuy, float $avgBuy, string $lang = 'hy'): array
{
    $dp = $lang === 'en' ? '.' : ',';
    $spreads = array_map(fn($r) => calc_spread($r['buy'], $r['sell']), $rows);
    $buys = array_column($rows, 'buy');
    $gap = $buys ? max($buys) - min($buys) : 0.0;
    return [
        'banks' => count($rows),
        'banks_total' => $banksTotal,
        'spread_min' => $spreads ? number_format(min($spreads), 1, $dp, '') : '0',
        'spread_max' => $spreads ? number_format(max($spreads), 1, $dp, '') : '0',
        'buy_gap' => number_format($gap, 2, '.', ''),
        'gap_10k' => number_format($gap * 10000, 0, '.', ' '),
        'avg_buy' => number_format($avgBuy, $avgBuy < 20 ? 2 : 2, '.', ''),
        'thousand' => number_format($bestBuy * 1000, 0, '.', ' '),
        'ten_k' => number_format($bestBuy * 10000, 0, '.', ' '),
    ];
}
